export const dictionaries = { en, rw, fr }
const get = (object, key) => String(key).split('.').reduce((value, part) => value && value[part], object)
const format = (text, values = {}) => String(text).replace(/\{(\w+)\}/g, (_, name) => values[name] ?? `{${name}}`)
export const translate = (key, language = 'en', values = {}) => {
  const direct = get(dictionaries[language], key)
  if (typeof direct === 'string') return format(direct, values)
  const message = `[i18n] Missing ${language} translation key: ${key}`
  if (import.meta.env.DEV) throw new Error(message)
  return ''
}
const leafKeys = (source, prefix = '') => Object.entries(source).flatMap(([key, value]) => {
  const fullKey = prefix ? `${prefix}.${key}` : key
  return value && typeof value === 'object' ? leafKeys(value, fullKey) : [fullKey]
})

// Kept deliberately strict: a new English key must be translated in both
// supported languages before it can be used in development.
export const auditDictionaries = () => leafKeys(en).flatMap((key) =>
  ['rw', 'fr'].filter((language) => typeof get(dictionaries[language], key) !== 'string').map((language) => `${language}:${key}`)
)
